import { describe, expect, it, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { MemoryRouter, Route, Routes } from 'react-router';
import { appRoutes } from '../../app/routes.tsx';
import { LEGAL_PATHS, LegalRedirect } from './LegalRedirect.tsx';
// Generated by scripts/build_legal_pages.py; Vite copies public/ into the build unchanged.
import privacyPage from '../../../public/privacy/index.html?raw';
import termsPage from '../../../public/terms/index.html?raw';
import guidelinesPage from '../../../public/guidelines/index.html?raw';
import supportPage from '../../../public/support/index.html?raw';

const STATIC_PAGES: Record<string, string> = { privacy: privacyPage, terms: termsPage, guidelines: guidelinesPage, support: supportPage };

function renderAt(url: string, navigate: (url: string) => void) {
  return render(
    <MemoryRouter initialEntries={[url]}>
      <Routes>{LEGAL_PATHS.map((path) => <Route key={path} path={path} element={<LegalRedirect path={path} navigate={navigate} />} />)}</Routes>
    </MemoryRouter>,
  );
}

describe('legal pages on the web build', () => {
  it('registers a route for each App Store page so a SPA fallback hands over to the static file', () => {
    const paths = appRoutes.map((route) => route.path);
    for (const path of ['/privacy', '/terms', '/guidelines', '/support']) expect(paths).toContain(path);
  });

  it('replaces /<page> with the static /<page>/ document', () => {
    const navigate = vi.fn();
    renderAt('/terms', navigate);
    expect(navigate).toHaveBeenCalledWith('/terms/');
    expect(screen.getByRole('link', { name: 'fancyabite.uk/terms/' }).getAttribute('href')).toBe('/terms/');
  });

  it('does not loop when the host has no static file and serves the app at /<page>/', () => {
    const navigate = vi.fn();
    renderAt('/privacy/', navigate);
    expect(navigate).not.toHaveBeenCalled();
    expect(screen.getByText(/This page is available at/)).toBeTruthy();
  });

  it.each(['privacy', 'terms', 'guidelines', 'support'])('ships an accessible static %s page linking the other pages', (slug) => {
    const page = STATIC_PAGES[slug]!;
    expect(page.startsWith('<!doctype html>')).toBe(true);
    expect(page).toContain('<html lang="en-GB">');
    expect(page).toContain('name="viewport" content="width=device-width, initial-scale=1"');
    expect(page).toMatch(/<title>[^<]+ · Fancy<\/title>/);
    expect(page).toContain(`<a href="/${slug}" aria-current="page">`);
    for (const other of ['privacy', 'terms', 'guidelines', 'support']) expect(page).toContain(`href="/${other}"`);
    expect(page).not.toMatch(/<script/i);
    // Only same-site assets; external links go to the regulator or Google's policy, nothing is loaded from elsewhere.
    const external = [...page.matchAll(/(href|src)="(https?:[^"]+)"/g)].map((m) => [m[1], new URL(m[2]!).host]);
    for (const [attribute, host] of external) {
      expect(attribute).toBe('href');
      expect(['ico.org.uk', 'policies.google.com']).toContain(host);
    }
  });
});
